<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { getAdminExploreComments, getAdminExplorePost, getAdminExplorePosts, updateAdminExploreCommentStatus, updateAdminExplorePostStatus } from '../api/admin-explore'

const result = ref({ records: [], total: 0 }); const loading = ref(false); const detail = ref(null); const comments = ref([]); const visible = ref(false); const query = reactive({ page: 1, size: 10, keyword: '', shopId: null, userId: null, status: '' })
function time(value) { return value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '' }
async function load() { loading.value = true; try { result.value = await getAdminExplorePosts({ ...query, status: query.status || undefined }) } catch (error) { result.value = { records: [], total: 0 }; ElMessage.error(error.message || '内容加载失败') } finally { loading.value = false } }
async function open(row) { try { detail.value = await getAdminExplorePost(row.id); const data = await getAdminExploreComments(row.id, { page: 1, size: 100 }); comments.value = data.records || []; visible.value = true } catch (error) { ElMessage.error(error.message || '内容详情加载失败') } }
async function changePost(row) { const next = row.postStatus === 'PUBLISHED' ? 'DISABLED' : 'PUBLISHED'; try { await updateAdminExplorePostStatus(row.id, { status: next }); row.postStatus = next; if (detail.value?.id === row.id) detail.value.postStatus = next; ElMessage.success(next === 'PUBLISHED' ? '内容已恢复展示' : '内容已禁用') } catch (error) { ElMessage.error(error.message || '状态更新失败') } }
async function changeComment(row) { const next = row.commentStatus === 'PUBLISHED' ? 'DISABLED' : 'PUBLISHED'; try { await updateAdminExploreCommentStatus(row.id, { status: next }); row.commentStatus = next; ElMessage.success(next === 'PUBLISHED' ? '评论已恢复展示' : '评论已禁用') } catch (error) { ElMessage.error(error.message || '评论状态更新失败') } }
onMounted(load)
</script>

<template><section class="admin-explore"><div class="heading"><div><p>CONTENT REVIEW</p><h1>探店内容管理</h1><span>使用状态审核保留内容与评论历史，不默认删除业务数据。</span></div></div><el-card shadow="never"><el-form class="filters" @submit.prevent="load"><el-input v-model="query.keyword" clearable placeholder="标题关键词"/><el-input v-model="query.shopId" clearable placeholder="店铺 ID"/><el-input v-model="query.userId" clearable placeholder="用户 ID"/><el-select v-model="query.status" clearable placeholder="全部状态"><el-option label="展示中" value="PUBLISHED"/><el-option label="已禁用" value="DISABLED"/><el-option label="用户已删除" value="DELETED"/></el-select><el-button type="primary" @click="query.page=1;load()">查询</el-button><el-button @click="Object.assign(query,{page:1,keyword:'',shopId:null,userId:null,status:''});load()">重置</el-button></el-form></el-card><el-card shadow="never" class="table"><el-table v-loading="loading" :data="result.records" empty-text="暂无探店内容"><el-table-column prop="title" label="标题" min-width="180" show-overflow-tooltip/><el-table-column prop="authorName" label="用户" width="120"/><el-table-column prop="shopName" label="店铺" width="140"/><el-table-column label="互动" width="110"><template #default="{row}">{{row.likeCount||0}} 赞 / {{row.commentCount||0}} 评</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.postStatus==='PUBLISHED'?'success':row.postStatus==='DISABLED'?'warning':'info'">{{row.postStatus==='PUBLISHED'?'展示中':row.postStatus==='DISABLED'?'已禁用':'已删除'}}</el-tag></template></el-table-column><el-table-column label="发布时间" width="174"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="160" fixed="right"><template #default="{row}"><el-button text type="primary" @click="open(row)">详情</el-button><el-button v-if="row.postStatus!=='DELETED'" text :type="row.postStatus==='PUBLISHED'?'danger':'success'" @click="changePost(row)">{{row.postStatus==='PUBLISHED'?'禁用':'恢复'}}</el-button></template></el-table-column></el-table><el-pagination v-if="result.total" v-model:current-page="query.page" :page-size="query.size" :total="result.total" layout="total, prev, pager, next" @current-change="load"/></el-card><el-drawer v-model="visible" title="探店内容详情" size="min(760px,100%)"><template v-if="detail"><h2>{{detail.title}}</h2><p class="meta">{{detail.authorName}} · {{detail.shopName}} · {{time(detail.createdAt)}}</p><p class="content">{{detail.content}}</p><div v-if="detail.images?.length" class="images"><el-image v-for="image in detail.images" :key="image" :src="image" fit="cover" preview-teleported/></div><el-divider>评论管理</el-divider><el-empty v-if="!comments.length" description="暂无评论" :image-size="52"/><div v-for="comment in comments" :key="comment.id" class="comment"><div><strong>{{comment.authorName}}</strong><p>{{comment.content}}</p><span>{{time(comment.createdAt)}}</span></div><el-button text :type="comment.commentStatus==='PUBLISHED'?'danger':'success'" @click="changeComment(comment)">{{comment.commentStatus==='PUBLISHED'?'禁用':'恢复'}}</el-button></div></template></el-drawer></section></template>
<style scoped>.admin-explore{max-width:1440px;margin:0 auto}.heading{margin-bottom:20px}.heading p{margin:0 0 6px;color:#5d7eb6;font-size:12px;font-weight:700;letter-spacing:.12em}.heading h1{margin:0;color:#213758}.heading span,.meta,.comment span{color:#7c8da5}.filters{display:flex;gap:10px;flex-wrap:wrap}.filters .el-input,.filters .el-select{width:170px}.table{margin-top:16px}.content{line-height:1.8;white-space:pre-wrap}.images{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.images .el-image{height:180px}.comment{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid #edf1f6}.comment p{margin:6px 0;color:#42566f}.comment span{font-size:12px}@media(max-width:700px){.filters .el-input,.filters .el-select{width:100%}}</style>
